import sys;sys.path.insert(0,'/mnt/c/WSL/davita/translations/xid9')
from h import *
P=[]
P.append(R(3755,"Jus Hijau","Membuat jus adalah tren kesehatan yang meningkat pesat dalam beberapa tahun terakhir. Jus Hijau dibuat dengan buah dan sayuran berkalium lebih rendah untuk membantu mereka yang menjalani diet ginjal tetap berada dalam target kalium rencana makan mereka.","2","3/4 cangkir (6 ons)",
["2 apel hijau sedang","1/2 lemon","1/2 cangkir nanas segar","1 mentimun sedang"],
["Cuci semua bahan dengan baik.","Buang bagian tengah apel.","Proses semua bahan melalui juicer. Bagi menjadi 2 porsi dan nikmati!"],
["Konsultasikan dengan ahli gizi Anda ketika memasukkan jus ke dalam diet ginjal Anda. Campuran jus tinggi kalium dan mungkin tidak dianjurkan jika pengendalian kalium menjadi masalah.","Pastikan menghitung 3/4 cangkir (6 ons) sebagai 1 porsi sayuran dan 2 porsi buah dari target harian Anda agar tetap dalam target kalium Anda untuk hari itu."],
["1-1/2 buah, kalium sedang","1 sayuran, kalium rendah"]))
P.append(R(3757,"Buncis Pedas Deviled","Tambahkan kejutan cita rasa pada hidangan Anda berikutnya dengan resep Buncis Pedas Deviled yang ramah ginjal ini. Mustard kuning, lada hitam, dan saus Worcestershire mengubah buncis yang jinak menjadi sajian yang lezat luar biasa.","4","1/2 cangkir",
["2 cangkir buncis beku","5 sendok teh mentega tanpa garam","2 sendok teh mustard","1/2 sendok teh lada hitam","1 sendok teh saus Worcestershire","1 sendok makan remah roti berbumbu"],
["Siapkan buncis sesuai petunjuk pada kemasan.","Buat saus dengan mencampurkan 2 sendok teh mentega leleh, mustard, lada, dan saus Worcestershire. Panaskan dalam microwave selama 30 detik.","Aduk saus dengan buncis matang yang panas.","Campurkan sisa margarin (leleh) dengan remah roti. Taburkan di atas buncis dan sajikan."],
["Gunakan buncis segar sebagai pengganti buncis beku saat sedang musimnya."],
["1 sayuran, kalium rendah","1 lemak"]))
P.append(R(3758,"Camilan Campur Madu-Maple","Seorang ahli gizi DaVita membagikan camilan ramah ginjal yang bergizi sekaligus lezat: Camilan Campur Madu-Maple.","24","1 cangkir",
["3 cangkir sereal Golden Grahams®","5 cangkir sereal Rice Chex®","10 ons biskuit camilan Cinnamon Teddy Grahams®","6 ons pretzel tanpa garam","1/2 cangkir mentega tanpa garam","1/3 cangkir gula merah tua","1/4 cangkir madu","1/4 cangkir sirup maple","5 ons cranberry kering, manis","3 ons keripik apel"],
["Campurkan Golden Grahams, Rice Chex, Teddy Grahams, dan pretzel dalam mangkuk besar.","Lelehkan mentega dalam panci kecil; tambahkan gula merah, madu, dan sirup maple. Masak dengan api kecil hingga gula meleleh.","Tuang di atas campuran sereal dan aduk rata hingga semua potongan terlapisi.","Panaskan oven terlebih dahulu hingga 325° F.","Siapkan 3 loyang jelly roll dengan melapisinya dengan aluminium foil dan menyemprot foil dengan semprotan masak. (Dapat dilakukan dalam 3 kali panggang). Ratakan campuran sereal di atas loyang. Panggang pada suhu 325° F selama 20 menit; aduk sekali di tengah waktu.","Campurkan cranberry dan keripik apel; bagi rata ke semua loyang dan aduk.","Panggang 5 menit lagi; dinginkan sepenuhnya dan simpan dalam wadah kedap udara."],
["Untuk sentuhan ekstra, taburi campuran camilan dengan bumbu Mrs. Dash® Caribbean Citrus atau Fiesta Lime.","Jika Anda menderita diabetes, kurangi ukuran porsi menjadi 1/2 cangkir untuk camilan dengan karbohidrat lebih rendah.","Carilah keripik apel di bagian produk segar jika Anda tidak menemukannya di bagian camilan.","Bagikan porsi ekstra kepada keluarga dan teman, atau buat setengah resep untuk menghasilkan lebih sedikit."],
["2 pati","1 buah, kalium rendah","1 lemak"]))
P.append(R(3760,"Wortel Glasir","Wortel yang manis alami dapat dipercantik dengan sedikit jahe, jus apel, dan beberapa bahan lain untuk menciptakan resep Wortel Glasir yang lezat dan ramah ginjal ini. Resep cepat dan mudah ini mempercantik sayuran yang sudah lezat sehingga menjadi sajian istimewa.","4","1/2 cangkir per porsi",
["2 wortel sedang","1 sendok makan gula","1 sendok teh tepung maizena","1/8 sendok teh garam","1/4 sendok teh jahe bubuk","1/4 cangkir jus apel","2 sendok makan mentega"],
["Iris wortel setebal 1 inci. Masukkan wortel dan 1/4 cangkir air ke dalam panci. Tutup dan masak hingga sedikit empuk.","Campurkan gula, tepung maizena, garam, jahe, jus apel, dan mentega leleh. Tuang campuran ke atas wortel dan air.","Masak sambil sesekali diaduk selama 10 menit atau hingga campuran mengental."],
["Wortel segar paling baik tetapi Anda dapat menggunakan wortel beku sebagai pengganti.","Jika diinginkan, ganti jahe dengan kayu manis bubuk."],
["1 sayuran, kalium sedang","1 lemak"]))
P.append(R(3762,"Pir Berbumbu Segar","Jika Anda menginginkan pencuci mulut yang berbeda namun lezat, cobalah resep ramah ginjal Pir Berbumbu Segar.","12","4 irisan pir atau 1/12 resep",
["6 pir sedang, dikupas dan diiris","3/4 cangkir campuran gula merah Splenda®","2 sendok makan jahe kristal","1-1/2 sendok teh ekstrak rum","1/4 sendok teh kayu manis bubuk","1/8 sendok teh allspice bubuk","1 sendok makan margarin"],
["Panaskan oven terlebih dahulu hingga 350° F.","Tata irisan pir dalam loyang 11” x 7” x 2”.","Campurkan campuran gula merah Splenda, jahe, ekstrak rum, kayu manis, dan allspice.","Taburkan campuran gula merah di atas pir.","Taruh potongan kecil margarin di atasnya.","Panggang selama 20 menit.","Sajikan panas atau simpan di lemari es minimal 1 jam untuk disajikan dingin."],
["Pir Bartlett dan Bosc adalah varietas terbaik untuk dipanggang.","Orang yang tidak menderita diabetes mungkin lebih suka menggunakan gula merah biasa.","Ganti allspice dengan bumbu pumpkin pie jika diinginkan."],
["1 buah, kalium rendah"]))
P.append(R(3763,"Salsa Verde","Salsa Verde adalah saus lezat untuk enchilada ayam, tetapi juga topping yang bagus untuk telur, taco, atau hidangan Meksiko favorit Anda.","10","1/4 cangkir",
["6 tomatillo sedang (sekitar 1/2 pon)","1 cabai jalapeño sedang","1/2 bawang bombai putih atau kuning kecil","1 siung bawang putih","1/4 cangkir daun ketumbar segar, dipadatkan","1/4 sendok teh garam","1/4 sendok teh lada hitam","1 sendok teh air jeruk nipis"],
["Rendam tomatillo dalam mangkuk sedang berisi air selama 5 menit. Letakkan piring kecil di atas tomatillo agar tetap terendam. Sementara tomatillo direndam, lapisi loyang berpinggiran dengan aluminium foil dan panaskan broiler dengan rak 4 inci di bawah sumber panas.","Buang kulit ari dan tangkai apa pun dari tomatillo yang sudah direndam. Bilas residu lengket yang tersisa pada kulit. Keringkan tomatillo dan potong menjadi dua.","Buang tangkai jalapeño dan potong menjadi empat bagian. Potong bawang bombai menjadi empat bagian.","Letakkan tomatillo dan jalapeño dengan sisi potongan menghadap ke bawah di atas loyang yang sudah disiapkan. Letakkan siung bawang putih dan bawang bombai yang dipotong empat di atas loyang. Panggang dengan broiler selama 5 sampai 7 menit hingga sedikit kecokelatan atau muncul bintik-bintik gosong kecil. Sesuaikan waktu seperlunya dan perhatikan dengan saksama karena bahan bisa cepat gosong. Angkat dari oven.","Pindahkan dengan hati-hati bahan-bahan yang sudah dipanggang beserta cairannya ke dalam food processor atau blender. Tambahkan daun ketumbar, air jeruk nipis, garam, dan lada hitam.","Pulsekan campuran hingga halus tanpa ada potongan besar tomatillo yang tersisa. Berhati-hatilah agar tidak menjadi puree. Salsa akan encer, namun akan mengental setelah disimpan di lemari es selama beberapa jam."],
["Buang biji dan urat jalapeño untuk menghasilkan salsa yang ringan, atau tambahkan satu jalapeño lagi untuk meningkatkan kepedasan.","Pilih tomatillo yang keras. Merendam tomatillo membantu menghilangkan residu lengket pada kulit.","Salsa Verde dapat disimpan dalam wadah kedap udara di lemari es hingga seminggu, atau di freezer untuk digunakan nanti.","Sajikan hangat atau dingin di atas telur, taco, atau hidangan Meksiko favorit Anda."],
["1/2 sayuran, kalium rendah"]))
P.append(R(3765,"Casserole Wortel-Apel","Ahli gizi ginjal DaVita, Maria dari North Carolina, membagikan resepnya untuk Casserole Wortel-Apel yang ramah ginjal, hidangan rendah lemak, rendah kalium, dan bebas kolesterol yang dapat dinikmati oleh mereka yang menjalani diet diabetes, cuci darah, atau PGK non-dialisis.","10","3/4 cangkir",
["6 wortel besar","4 apel besar","5 sendok makan tepung terigu serbaguna","2 sendok makan gula merah","1/2 sendok teh pala bubuk","3 sendok makan mentega","1/2 cangkir jus apel"],
["Panaskan oven terlebih dahulu hingga 350° F.","Kupas dan iris wortel dan apel. Didihkan 1 quart air dalam panci berukuran sedang. Rebus wortel selama 5 menit atau hingga empuk. Tiriskan.","Susun wortel dan apel berlapis dalam piring casserole besar.","Menggunakan garpu, campurkan tepung, gula merah, dan pala dalam mangkuk kecil. Campurkan mentega untuk membuat topping remah.","Taburkan campuran tepung di atas wortel dan apel lalu siram dengan jus.","Panggang selama 50 menit atau hingga apel dan wortel empuk dan topping berwarna cokelat keemasan."],
["Enam wortel besar akan menghasilkan 6 cangkir dan 4 apel besar akan menghasilkan 4 cangkir setelah dikupas dan diiris.","Casserole dapat disusun sebelumnya dan disimpan di lemari es. Panaskan saat siap disantap.","Ganti gula merah dengan pemanis Splenda® jika menginginkan kandungan karbohidrat yang lebih rendah."],
["1 buah, kalium rendah","1 sayuran, kalium sedang","1/2 lemak"]))
P.append(R(3766,"Slider Dijon","Slider Dijon ramah ginjal dan lezat! Nikmati satu sebagai hidangan pembuka atau gandakan dan santap 2 slider untuk satu kali makan.","12","1 slider",
["1 bawang bombai besar","12 roti makan malam, manis, Hawaiian","1-1/2 pon daging sapi giling","1 sendok makan minyak kanola","2 sendok makan mustard Dijon","12 irisan acar manis"],
["Cincang bawang bombai. Belah dua roti dan sisihkan.","Bagi daging sapi giling menjadi 12 patty, buat dengan diameter sedikit lebih besar daripada roti.","Dalam wajan besar dengan api sedang, tumis bawang bombai dalam minyak hingga bening.","Letakkan patty daging sapi giling di atas bawang bombai dan goreng hingga matang, tekan agar bawang bombai menempel pada patty.","Letakkan satu patty daging dalam setiap roti, beri topping 1/2 sendok teh mustard dan 1 irisan acar sebelum disajikan."],
["Sajikan sebagai hidangan pembuka atau gandakan untuk hidangan utama.","Pilih merek irisan acar manis dengan natrium terendah."],
["1-1/2 daging","1-1/2 pati"]))
P.append(R(3767,"Isian Cranberry Herba Segar","Dalam menjalani diet cuci darah, hari raya bisa menjadi masa yang menantang. Berikut resep lezat dari tim ahli gizi ginjal DaVita untuk Isian Cranberry Herba Segar yang ramah ginjal.","6","1/2 cangkir",
["1/2 cangkir bawang bombai","1/2 cangkir seledri","1/2 sendok makan peterseli segar","1/2 sendok makan sage segar","1/2 sendok makan rosemary segar","1/2 sendok makan thyme segar","8 lembar roti","1/4 cangkir mentega tanpa garam","1/2 sendok teh lada hitam","2 sendok teh bumbu unggas","1/2 cangkir cranberry kering, manis","1/2 cangkir pengganti telur cair rendah kolesterol","1/4 cangkir kaldu ayam atau kalkun"],
["Cincang bawang bombai dan seledri. Cincang herba segar. Potong roti menjadi kubus 1/2 inci.","Lelehkan mentega dalam wajan antilengket. Tumis bawang bombai dan seledri hingga empuk. Angkat dari api.","Masukkan kubus roti, lada, bumbu unggas, herba segar, dan cranberry lalu aduk.","Campurkan produk telur dan kaldu. Tuang ke campuran roti dan aduk perlahan.","Masukkan isian ke dalam rongga tubuh dan leher kalkun untuk dimasak, atau panggang isian secara terpisah dalam loyang yang sudah disemprot semprotan masak antilengket pada suhu 350º F selama 45 menit."],
["Untuk hasil terbaik gunakan roti yang sudah satu hari.","Jika herba segar tidak tersedia, gunakan 1 sendok teh herba kering.","Jika kaldu jeroan tidak tersedia, gunakan kaldu ayam rendah natrium."],
["1 pati","1 lemak","1/2 buah, kalium rendah"]))
P.append(R(3770,"Pancake Daun Bawang","Pancake Daun Bawang adalah pancake Tionghoa tanpa ragi yang dibumbui daun bawang dan minyak wijen lalu digoreng hingga cokelat renyah.","8","1 pancake",
["5 batang daun bawang","1-3/4 cangkir tepung terigu serbaguna","1/4 cangkir tepung maizena","1/2 cangkir air mendidih","1/4 cangkir air dingin","1 sendok makan minyak wijen","1 sendok makan minyak kanola"],
["Cincang halus daun bawang dan sisihkan.","Campurkan tepung terigu dan tepung maizena dengan rata dalam mangkuk. Menggunakan garpu, aduk dengan air mendidih. Tambahkan air dingin dan campurkan dengan tangan hingga semua tepung menyatu.","Tutup adonan dan diamkan selama 20 menit.","Lumuri tangan dengan tepung agar adonan tidak lengket dan bentuk adonan menjadi tali panjang. Potong menjadi 8 bagian.","Di atas permukaan yang ditaburi tepung, giling satu potong adonan setipis mungkin. Olesi dengan minyak wijen dan taburi dengan 2 sendok makan daun bawang.","Gulung seperti jelly roll. Lilitkan gulungan seperti cinnamon bun. Giling hingga setebal 1/4 inci.","Ulangi dengan potongan adonan lainnya.","Panaskan minyak kanola dengan api sedang-besar dalam wajan antilengket (atau gunakan semprotan masak). Goreng setiap pancake, sekitar 1 sampai 2 menit per sisi, hingga adonan sedikit mengembang dan menjadi renyah. Sajikan segera."],
["Satu batang daun bawang menghasilkan sekitar 2 sendok makan setelah dipangkas dan dicincang.","Beri topping saus cabai sriracha atau celupkan ke saus cabai manis rendah natrium."],
["1-1/2 pati","1/2 lemak"]))
P.append(R(3771,"Salad Bit dan Mentimun","Salad Bit dan Mentimun adalah resep ramah ginjal yang renyah dan sejuk untuk dinikmati sebagai hidangan pendamping.","6","3/4 cangkir",
["1 mentimun","15 ons bit iris kalengan rendah natrium","4 sendok teh cuka balsamic","2 sendok teh minyak kanola","2 sendok makan keju Gorgonzola"],
["Iris tipis mentimun.","Letakkan irisan bit di atas piring saji.","Susun irisan mentimun di atas irisan bit.","Siram dengan cuka dan minyak.","Taburi dengan keju Gorgonzola."],
["Keju Gorgonzola adalah keju biru buatan Italia. Karena keju biru memiliki cita rasa yang kuat dan sangat tinggi natrium (400 mg/ons), porsi yang sangat kecil digunakan dalam resep ini.","Dinginkan bit sebelum menyiapkan resep."],
["1-1/2 sayuran, kalium sedang","1/2 lemak"]))
P.append(R(3774,"Sayap Buffalo","Berikut resep Sayap Buffalo yang ramah ginjal dari seorang ahli gizi DaVita. Baik Anda menyukai sayap ayam, drumette, atau tenders ayam tanpa tulang, Anda dapat memodifikasi resep yang menggoda ini sesuai keinginan. Dan penderita penyakit ginjal, diabetes, atau yang menjalani cuci darah dapat menyantap hidangan pembuka yang lezat ini.","12","2 sayap",
["8 sendok makan mentega tanpa garam","1/3 cangkir saus cabai pedas Tabasco®","1/4 cangkir saus paprika merah panggang","1/4 cangkir saus tomat rendah natrium","1 sendok makan minyak zaitun","1/2 sendok teh bubuk bawang putih","1/2 sendok teh campuran bumbu Italia kering","24 drumette sayap ayam"],
["Panaskan oven terlebih dahulu hingga 400° F.","Lelehkan mentega dalam panci.","Tambahkan saus pedas, saus paprika merah, saus tomat, minyak zaitun, bubuk bawang putih, dan bumbu Italia lalu aduk hingga tercampur. Angkat panci dari api.","Letakkan sayap ayam dalam loyang.","Tuang saus di atas sayap dan panggang selama 30 sampai 35 menit. Periksa kematangannya.","Sajikan sayap panas atau simpan dalam wadah penghangat tertutup atau crock pot hingga siap disajikan."],
["Beli drumette sayap segar. Satu kemasan 1-1/4 pon berisi 12 drumette. Jika tidak tersedia, minta tukang daging memotong sayap ayam utuh menjadi ukuran drumette.","Potongan ayam tanpa tulang dapat digunakan dalam resep ini. Periksa kematangan setelah 20 menit.","Merek saus pedas sangat bervariasi dalam kandungan natriumnya. Pilih merek dengan natrium kurang dari 140 mg per sendok teh.","Buat Saus Tomat Paprika Merah Panggang (di bawah Saus & Bumbu dalam koleksi resep DaVita.com) dan gunakan 1/2 cangkir ditambah saus Tabasco jika diinginkan."],
["1 daging","1 lemak"]))
P.append(R(3775,"Salad Ayam","Joyce, ahli gizi ginjal DaVita dari Pennsylvania, meminta saran dari sekelompok kritikus kuliner yang tangguh dan terkenal dengan selera yang cermat serta standar kualitas yang tinggi — para pasien cuci darahnya. Ia mendapat dua jempol untuk resep Salad Ayamnya yang menampilkan apel, seledri, dan kayu manis. Resep ramah ginjal ini kaya cita rasa dan kemungkinan besar akan disukai kelompok kritikus dapur Anda sendiri.","4","1 cangkir",
["1-1/2 cangkir ayam matang","1/2 cangkir seledri","2 cangkir apel","3/4 cangkir anggur tanpa biji","1/4 cangkir mayones","1/4 sendok teh kayu manis bubuk","1/2 sendok teh air lemon"],
["Potong dadu ayam matang. Potong dadu seledri dan apel. Belah dua anggur.","Dalam mangkuk besar, campurkan ayam, seledri, apel, dan belahan anggur.","Tambahkan mayones, kayu manis, dan air lemon. Aduk hingga bahan terlapisi.","Dinginkan minimal 30 menit sebelum disajikan."],
["Sajikan Salad Ayam sebagai isian sandwich atau sebagai salad hidangan utama di atas selada."],
["2 daging","1 buah, kalium rendah","1 lemak"]))
P.append(R(3776,"Makan Malam Zucchini, Kacang Hitam, dan Nasi","Ahli gizi ginjal DaVita, Cindy dari Florida, senang memasak vegetarian dan membuat hidangan satu wajan yang menghemat waktu. Resepnya, Makan Malam Zucchini, Kacang Hitam, dan Nasi, adalah cara yang bagus untuk tidak menggunakan daging namun tetap mendapatkan protein dan cita rasa.","4","1-1/2 cangkir",
["1 sendok makan minyak kanola","1-1/2 cangkir zucchini segar","15 ons kacang hitam kalengan tanpa tambahan garam","1 tomat sedang","1 cangkir air","1 cangkir nasi putih instan, mentah","1/4 cangkir campuran keju cheddar dan Monterey jack parut"],
["Dalam wajan besar, panaskan minyak dengan api sedang-besar.","Iris zucchini memanjang dan cincang.","Masukkan zucchini ke dalam wajan dan tumis hingga empuk, sering diaduk.","Tiriskan dan bilas kacang hitam dari kaleng, lalu masukkan kacang ke dalam wajan.","Cincang tomat dan masukkan ke wajan bersama air.","Besarkan api dan didihkan.","Tambahkan nasi; aduk rata.","Angkat dari api dan diamkan selama 7 menit atau hingga cairan terserap.","Taburi setiap porsi dengan 1 sendok makan campuran keju, jika diinginkan."],
["Tambahkan air lemon segar peras, jika diinginkan untuk cita rasa tambahan.","Nasi merah instan dapat digunakan sebagai pengganti nasi putih instan, jika menginginkan pilihan biji-bijian utuh.","Campuran keju bersifat opsional; hilangkan jika kadar fosfor Anda tinggi.","Meskipun kacang tinggi kalium dan fosfor, Anda tetap dapat memasukkannya ke dalam diet ginjal ketika digunakan sebagai pengganti hidangan utama daging. Kacang adalah sumber serat yang sangat baik."],
["2 pati","2 sayuran, kalium sedang","1 lemak"]))
P.append(R(3779,"Roti Apel Zucchini","Ahli gizi ginjal DaVita, Brittany dan Holly dari Illinois, berkolaborasi membagikan Roti Apel Zucchini yang ramah ginjal. Roti yang lembap dan kaya cita rasa ini adalah penutup sempurna untuk makan siang atau makan malam. Atau nikmati sendiri dengan secangkir teh untuk camilan yang memuaskan.","32","1 iris",
["3-3/4 cangkir ditambah 2 sendok makan tepung terigu serbaguna","1 apel Granny Smith sedang","2 zucchini sedang","4 butir telur besar","1/2 cangkir minyak nabati","3/4 cangkir gula pasir","1 cangkir gula merah","1 sendok teh ekstrak vanila","1-1/2 sendok teh soda kue","1/2 sendok teh garam","3 sendok teh kayu manis bubuk","2 sendok makan mentega dingin tanpa garam"],
["Panaskan oven terlebih dahulu hingga 350˚ F. Olesi dengan minyak dan taburi tepung dua loyang roti 9 x 5 inci menggunakan 2 sendok makan tepung.","Kupas dan cincang apel; parut zucchini.","Dalam mangkuk besar, campurkan telur, minyak, gula pasir, 3/4 cangkir gula merah (atau 6 sendok makan campuran gula merah Splenda®), dan vanila.","Dalam mangkuk besar terpisah, campurkan soda kue, 3-1/2 cangkir tepung, garam, dan 2 sendok teh kayu manis.","Aduk campuran tepung ke dalam campuran telur. Jangan terlalu banyak diaduk.","Lipat apel dan zucchini lalu tuang campuran ke dalam loyang roti. Ratakan campuran.","Panggang selama 40 menit.","Sementara roti dipanggang, siapkan topping remah: campurkan sisa 1/4 cangkir tepung, 1/4 cangkir gula merah (atau 2 sendok makan campuran gula merah Splenda®), dan 1 sendok teh kayu manis. Potong mentega ke dalamnya hingga campuran sangat berremah.","Keluarkan roti dari oven setelah dipanggang selama 40 menit dan tambahkan topping remah.","Panggang 10 menit lagi atau hingga tusuk gigi keluar bersih (dari bagian tengah roti).","Dinginkan selama 10 menit, lalu keluarkan roti dari loyang dan pindahkan ke rak kawat hingga dingin sepenuhnya.","Potong setiap roti menjadi 16 irisan sebelum disajikan."],
["Jika menggunakan pengganti gula Splenda® sebagai pengganti gula, karbohidrat berkurang menjadi 13 g per porsi.","Jika mengganti gula merah dengan pemanis campuran gula merah Splenda®, kurangi menjadi 8 sendok makan.","Bungkus satu roti dengan plastik pembungkus dan masukkan ke dalam kantong pembeku untuk disajikan di lain waktu.","Untuk versi lebih rendah lemak, gunakan 1/2 cangkir saus apel tanpa gula sebagai pengganti minyak nabati."],
["1-1/2 pati","1 lemak"]))
save(6,P)
